import torch
import torch.distributed as dist
import torch.nn.functional as F


def _ws_rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size(), dist.get_rank()
    return 1, 0


class _AllGatherLastDim(torch.autograd.Function):
    """Forward: all_gather local shards and concat along last dim.
    Backward: return this rank's slice of the incoming gradient."""

    @staticmethod
    def forward(ctx, x):
        ws, rank = _ws_rank()
        ctx.ws = ws
        ctx.rank = rank
        if ws == 1:
            return x
        x = x.contiguous()
        shards = [torch.empty_like(x) for _ in range(ws)]
        dist.all_gather(shards, x)
        return torch.cat(shards, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        ws = ctx.ws
        rank = ctx.rank
        if ws == 1:
            return grad_output
        chunk = grad_output.shape[-1] // ws
        return grad_output[..., rank * chunk:(rank + 1) * chunk].contiguous()


class _AllReduceSum(torch.autograd.Function):
    """Forward: all_reduce (sum) across ranks.
    Backward: identity (gradient is broadcast unchanged)."""

    @staticmethod
    def forward(ctx, x):
        ws, _ = _ws_rank()
        if ws == 1:
            return x
        x = x.clone()
        dist.all_reduce(x)
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws, rank = _ws_rank()
        assert out_features % ws == 0, "out_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.out_features_per_partition = out_features // ws

        start = rank * self.out_features_per_partition
        end = start + self.out_features_per_partition
        w = master_weight[start:end, :].detach().clone().contiguous()
        self.weight = torch.nn.Parameter(w)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(self.out_features_per_partition,
                            dtype=self.weight.dtype, device=self.weight.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        local = F.linear(x, self.weight, self.bias)
        return _AllGatherLastDim.apply(local)


class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws, rank = _ws_rank()
        assert in_features % ws == 0, "in_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.in_features_per_partition = in_features // ws

        start = rank * self.in_features_per_partition
        end = start + self.in_features_per_partition
        w = master_weight[:, start:end].detach().clone().contiguous()
        self.weight = torch.nn.Parameter(w)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features,
                            dtype=self.weight.dtype, device=self.weight.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        local = F.linear(x, self.weight)
        out = _AllReduceSum.apply(local)
        if self.bias is not None:
            out = out + self.bias
        return out
